import{_ as l,o as e,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"Cap Table Skill：融资股权结构计算与复核","description":"","frontmatter":{"title":"Cap Table Skill：融资股权结构计算与复核","date":"2026-08-06T00:00:00.000Z","category":"Skill 技能","summary":"用于构建、核对和审计融资股权结构表，覆盖增资、老股转让、混合交易、多轮融资与连续反摊薄计算。","tags":[]},"headers":[],"relativePath":"skills/cap-table-skill.md","filePath":"skills/cap-table-skill.md","lastUpdated":1788339898000}'),r={name:"skills/cap-table-skill.md"};function s(o,a,p,n,c,h){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="cap-table-skill-融资股权结构计算与复核" tabindex="-1">Cap Table Skill：融资股权结构计算与复核 <a class="header-anchor" href="#cap-table-skill-融资股权结构计算与复核" aria-label="Permalink to &quot;Cap Table Skill：融资股权结构计算与复核&quot;">​</a></h1><p>这是一个面向融资交易的股权结构计算 Skill。它把注册资本、持股比例、投资价格和反摊薄条款转化为可追踪的计算过程，用于构建、复核和审计 Cap Table。</p><p><a href="https://github.com/Hellyai/cap-table-skill" target="_blank" rel="noreferrer">查看 GitHub 仓库 →</a></p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>融资股权表的难点不只是“算出一个比例”，而是确认每一个数字采用了正确口径：新股和老股是否被混淆、OS 取值时点是否正确、多轮触发是否承接了上一轮完整精度，以及协议中受保护的股份范围是否与计算一致。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li>普通增资、股权转让及投后股权结构计算；</li><li>新股与老股混合交易拆分；</li><li>多轮融资和连续反摊薄计算；</li><li>按协议核对 OCP、OS、NP、NS 及补偿数量；</li><li>股东、投资轮次和最终持股比例勾稽检查。</li></ul><h2 id="关键计算口径" tabindex="-1">关键计算口径 <a class="header-anchor" href="#关键计算口径" aria-label="Permalink to &quot;关键计算口径&quot;">​</a></h2><p>同一次触发发行对不同受保护轮次使用相同的发行前 OS，但分别使用各自 OCP；老股转让数量和价款不计入 NS、NP；连续融资承接上一轮完整精度的调整后价格，并在每轮使用实际发行前 OS。</p><h2 id="我的设计判断" tabindex="-1">我的设计判断 <a class="header-anchor" href="#我的设计判断" aria-label="Permalink to &quot;我的设计判断&quot;">​</a></h2><p>交易计算应当可以回溯。相比只展示最终百分比，我更关注每轮的输入、公式、增量补偿和最终累计权益能否互相勾稽，使律师、投资人和财务人员可以定位差异来自哪里。</p><h2 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h2><p>具体计算以已经签署或正在审阅的投资协议、股东协议及完整交易文件为准。仓库不包含客户或项目数据，输出不能替代对协议文本和交易事实的人工核验。</p><p><strong>开源许可：</strong> Apache License 2.0</p>',14)])])}const k=l(r,[["render",s]]);export{b as __pageData,k as default};
